with v(id,beschr,website,missie,plaats,bmin,bmax,btoel,bron) as (values
('44e0f1b7-1771-4083-b267-3bb56198489d','De Fundatie Van den Santheuvel, Sobbe is een Amsterdams vermogensfonds dat via meerdere onderliggende fondsen organisaties steunt die mensen helpen die moeite hebben om volwaardig mee te doen in de samenleving. Accenten liggen op zelfredzaamheid, integratie en praktische ondersteuning. Het fonds geeft projectsubsidies voor concrete initiatieven (geen exploitatiekosten), onder meer op het gebied van sport- en cultuurdeelname door jongeren, inclusie van en voorzieningen voor mensen met een beperking, kunst met sociale impact, sociale integratie, jeugdzorg en preventie van schooluitval, en ouderenzorg. Aanvragers moeten een rechtspersoon zijn (meestal een stichting); particulieren, bv''s en nv''s komen niet in aanmerking. Maximaal één toekenning per organisatie per jaar. Projecten buiten Nederland worden niet gesteund en vanaf 1 januari 2027 ook niet buiten Amsterdam.',null,null,'Amsterdam',null,null,null,'https://www.kindora.co/en/funders/fundatie-van-den-santheuvel-sobbe'),
('f0a1f072-2189-4658-b565-e7560f6668e0','Het Gieskes-Strijbis Fonds is een particulier vermogensfonds dat grootschalige, meerjarige en baanbrekende projecten steunt die bijdragen aan duurzame maatschappelijke ontwikkeling. Het fonds werkt proactief, scout zelf projecten en blijft na toekenning nauw betrokken. Er zijn vier aandachtsgebieden: natuur en milieu (een gezond voedselsysteem, biologische landbouw, minder schade door pesticiden, bescherming van de Noordzee), medisch onderzoek (verband tussen pesticideblootstelling en ziekten zoals Parkinson), kunst en cultuur (ontwikkeling van midcareer podiumkunstenaars via de Gieskes-Strijbis Podiumprijs, behoud van ambachten, landelijke culturele instellingen) en democratie en rechtsstaat (een veilige digitale ruimte, publiek debat, burgerparticipatie). Het werkgebied is Nederland met een internationale dimensie. Trefwoorden: duurzame landbouw, Noordzee, pesticiden, podiumkunsten, ambachten, rechtsstaat, digitale democratie.',null,null,null,null,null,null,'https://www.gieskesstrijbisfonds.nl/wp-content/uploads/2025/10/Beleidsplan-GSF-2024-2027-update-22-okt-2025.pdf'),
('be2a6bc4-06d4-4d4a-ac72-782e2ae30e9c','Het Hendrik Muller (Vaderlandsch) Fonds verstrekt studiebeurzen aan jonge, veelbelovende Nederlanders die in het buitenland willen studeren of onderzoek doen. De beurs is behoeftegericht: het fonds vult het tekort in het budget aan nadat de maximale DUO-studiefinanciering is benut. In aanmerking komen stages, onderzoeksprojecten, volledige masteropleidingen en promoties in het buitenland van minimaal vier aaneengesloten maanden; uitwisselingen, congressen en studiereizen vallen erbuiten. Voorwaarden zijn onder meer de Nederlandse of Surinaamse nationaliteit, een afgeronde bachelor, een voltijdse wo- of hbo-opleiding, een gemiddeld cijfer van minimaal 7,5 en aantoonbare financiële noodzaak. Aanvragen moeten vóór vertrek worden ingediend. Trefwoorden: studiebeurs, studeren in het buitenland, talentontwikkeling, promotieonderzoek, buitenlandstage.',null,null,'Den Haag',null,null,null,'https://www.european-funding-guide.eu/nl/node/72731'),
('2a97c8dd-3813-47c1-b159-b764fd86818f','De Iona Stichting is een internationaal, antroposofisch geïnspireerd particulier fonds uit Amsterdam dat initiatieven steunt gericht op sociale, culturele en spirituele ontwikkeling en vernieuwing, waarin mens, aarde en geest met elkaar verbonden zijn. Het fonds financiert projecten, onderzoek en reizen, onder meer op het gebied van architectuur (inclusief tuin- en landschapsarchitectuur), beeldende kunst, muziek en podiumkunsten. Aanvragen kunnen komen van personen en organisaties, waaronder kunstenaars uit het Koninkrijk der Nederlanden op elk niveau, ook amateurs, mits het werk aansluit bij de antroposofische visie en werkwijze. Beoordeling gebeurt op aansluiting bij de doelstelling, creativiteit, initiatiefkracht en samenhang tussen idealen, doelgroep, aanpak en begroting. Niet gesteund worden onder meer bouwkosten, boekuitgaven, professionele voorstellingen, films, tournees en residenties. Trefwoorden: antroposofie, spirituele vernieuwing, kunstprojecten, amateurkunst, landschapsarchitectuur.',null,null,'Amsterdam',null,null,null,'https://dutchculture.nl/en/grant/iona-foundation-project-support'),
('071a6061-bf16-4aa1-96d9-018c7580212a','De Janivo Stichting steunt projecten die bijdragen aan een betere samenleving waarin ieder een veilige en gezonde plek heeft en kansen krijgt voor creatieve, sociale en economische ontplooiing. De stichting richt zich op kinderen, jongeren en jongvolwassenen tot 25 jaar, binnen drie thema''s: maatschappij, kunst en wetenschappelijk medisch onderzoek. Alleen projecten in Nederland komen in aanmerking; stichtingen en verenigingen kunnen aanvragen, en beginnende makers kunnen terecht bij het Snelloket Jonge Makers. Gebruikelijke bijdragen liggen tussen 1.000 en 6.000 euro per project; hogere bedragen zijn uitzonderlijk mogelijk, bijvoorbeeld voor medisch onderzoek, na voorafgaand contact. Voorkeur gaat uit naar projecten die met eenvoudige middelen een groot bereik hebben, een voortrekkersrol vervullen en bovenlokale betekenis hebben. Andere fondsen worden niet gesteund. Trefwoorden: jeugd, talentontwikkeling, jonge makers, kunstprojecten, medisch onderzoek.',null,null,null,null,null,null,'https://www.janivostichting.nl/janivo-stichting'),
('aecc5ab6-f05f-45a6-9eef-d7727f870a0e','Kansfonds is een landelijk fonds uit Hilversum dat werkt aan innovatieve oplossingen voor dakloosheid, armoede en schulden, en sociale uitsluiting, vanuit de overtuiging dat iedereen recht heeft op een thuis. Samen met partners streeft het fonds naar structurele verandering. De drie hoofdthema''s zijn het uitbannen van dakloosheid, afrekenen met armoede en het tegengaan van uitsluiting. Daarnaast is er aandacht voor inloophuizen, noodhulp, slimme woonoplossingen, thuisloze jongeren en ongedocumenteerde mensen, met wortels in het katholiek sociaal denken. Programma''s omvatten onder meer een ETHOS-telling van dakloosheid, Alle jongeren een thuis, Thuisfonds, Afrekenen met schulden, Gewoon geld geven en Dreamers voor ongedocumenteerde jongeren. Trefwoorden: dak- en thuisloosheid, schuldhulp, bestaanszekerheid, woonoplossingen, ongedocumenteerden, inloophuizen.',null,null,'Hilversum',null,null,null,'https://www.kansfonds.nl/thema/dak-en-thuisloosheid/'),
('54659550-74b7-4941-8139-a2ae5675b402','De Kattendijke/Drucker Stichting is eind 2004 ontstaan uit een fusie tussen de Maurits van Kattendijke Stichting en de Thérèse Drucker Stichting. De stichting verleent financiële steun in Nederland wanneer het bestuur dit doelmatig en verantwoord acht. Zij steunt religieuze, culturele en sociale instellingen, met bijzondere aandacht voor jeugd en onderwijs. Aanvragen worden in principe alleen van instellingen gehonoreerd; individuele personen ontvangen in beginsel geen steun. Projecten in het buitenland worden doorgaans niet ondersteund. Over aanvraagprocedure, termijnen of bedragen geeft de bron geen informatie. Trefwoorden: jeugd, onderwijs, religieuze instellingen, culturele instellingen, sociale instellingen.',null,null,null,null,null,null,'https://dutchculture.nl/location/kattendijke-drucker-foundation'),
('6b6d0fd9-5936-4cf6-ab4e-94cd6f997703','De L''OCCITANE Foundation wil banden tussen mensen onderling en met de natuur versterken, zodat mensen beter samenleven (''Caring Ties''). Het fonds steunt projecten rond sociale verbinding (inclusie, zelfvertrouwen en zelfstandigheid via relaties) en verbinding met de natuur (natuur in de stad, ecosysteemvriendelijke praktijken, biodiversiteit). Voorbeelden zijn gedeelde woonvormen, culturele en gemeenschapshubs en het ombouwen van leegstand tot inclusieve leefomgevingen. Daarnaast noemt het fonds actiegebieden als zorg voor het gezichtsvermogen en empowerment van vrouwen. Werkgebied is vooral de Provence en Corsica (Frankrijk) en Burkina Faso. Het fonds werkt met meerjarige partnerschappen, ruimere ongeoormerkte financiering en beperkte rapportagelast.',null,null,null,null,null,null,'https://fondation.loccitane.com/'),
('11c28eab-cfcc-423d-803e-e22d7f02e4b1','De LSBS (Landelijke Stichting voor Blinden en Slechtzienden) is een vermogensfonds dat de integratie en het welzijn van mensen met een ernstige visuele beperking bevordert. Het fonds geeft projectbijdragen aan Nederlandse organisaties van en voor blinden en slechtzienden, steunt via in Nederland gevestigde organisaties projecten voor visueel gehandicapten in ontwikkelingslanden (jaarlijkse deadline), en draagt bij aan oogheelkundig wetenschappelijk onderzoek (o.a. drukkosten proefschriften, buitenlandse stages; onderzoeksgelden via UitZicht). Samen met Bartiméus Fonds en Visio is er een fonds voor cultuur en vrijetijdsbesteding van mensen met een visuele beperking. Exploitatiekosten en reeds uitgevoerde activiteiten worden niet vergoed.',null,null,'Ede',null,null,null,'https://www.kindora.co/en/funders/lsbs'),
('9cdc8495-b94c-490e-b0e7-de451a6a2051','De M.A.O.C. Gravin van Bylandt Stichting is een vermogensfonds dat bescheiden bijdragen (vaak rond 2.500 euro) geeft aan stichtingen en verenigingen met projecten van algemeen nut voor mens en dier in Nederland. Programma''s: Mens & Welzijn (met aandacht voor ouderen en lokale noodhulp, vaak via hulpbureaus), Kunst & Cultuur (geregistreerde musea en professionele podiumkunstgezelschappen, kleine festivals, beginnende gezelschappen), Restauraties & Onderhoud (publiek toegankelijke rijksmonumenten), Publicatie & Educatie (wetenschappelijk-historische publicaties) en Dier, Natuur & Milieu (dierenwelzijn, natuurbewustzijn). Geen steun aan individuen, religieuze, politieke of commerciële instellingen, leningen of projecten buiten Nederland. Aanvragen kan doorlopend online.',null,null,'Den Haag',null,null,null,'https://www.kindora.co/en/funders/m-a-o-c-gravin-van-bylandt-stichting'),
('eb1ed61b-d033-4957-8386-c3d607f711c0','Het N. van Ballegooijen Fonds is een familiefonds dat gerichte, relatief kleine bijdragen (meestal onder 5.000 euro) geeft om de kwaliteit van leven te verbeteren met praktische, tastbare steun. Er zijn drie aanvraagsporen: lokale initiatieven in en rond Altena, landelijke Nederlandse goede doelen met meetbare maatschappelijke of ecologische impact, en geselecteerde internationale hulpprojecten. Aandachtsgebieden zijn armoedebestrijding en basisbehoeften, steun aan kinderen en jongeren, natuurbehoud en biodiversiteit, cultureel erfgoed en lokale geschiedenis, gehandicaptenzorg en respijtzorg, en ontwikkelingssamenwerking en medische hulp. Voorkeur gaat uit naar ANBI''s en non-profits met concrete resultaten in het veld in plaats van hoge personeelskosten; aanvragen gaan via vaste vergaderdata en deadlines.',null,null,'Heesbeen',null,null,null,'https://www.kindora.co/en/funders/stichting-n-van-ballegooyen-fonds'),
('2f2f0187-ad06-49e6-81f7-ff122c7934da','Nationaal Fonds Kinderhulp biedt financiële steun aan kinderen en jongeren van 0 tot 21 jaar in Nederland die in armoede opgroeien, zodat zij kunnen meedoen en gelijke kansen krijgen. Aanvragen lopen via intermediairs zoals maatschappelijke organisaties, jeugdhulp en gemeenten; Kinderhulp hanteert geen inkomensgrenzen en fungeert als vangnet wanneer andere voorzieningen ontbreken. Hulp wordt gegeven in geld of natura, bijvoorbeeld voor dagjes uit, vakanties en kampen, kleding, kamerinrichting, studiekosten en laptops, speelgoed, fietsen, zwemles, zomerpakketten, Sinterklaascadeaus (Actie Pepernoot), boeken en starterspakketten voor jongeren die op zichzelf gaan wonen. Het fonds vraagt daarnaast aandacht voor kinderarmoede.',null,null,'Deventer',null,null,null,'https://kinderhulp.nl/content/uploads/2023/10/Kinderhulp-jaarverslag-2022-incl-accountantsverklaring.pdf'),
('fe43e1a3-fe50-4d30-9106-871a61424a17','Het Nationaal Fonds voor de Sport financiert projecten die sport inzetten als middel om de samenleving te versterken, met accenten op fysieke en mentale gezondheid, inclusie, persoonlijke ontwikkeling en sociale cohesie binnen het Koninkrijk der Nederlanden. Steun loopt vooral via thematische open oproepen voor sportverenigingen (bijv. sociale cohesie, fysieke gezondheid in samenwerking met zorgprofessionals) en via fondsen op naam, zoals het Fonds Breedtesport voor Mensen met een Visuele Beperking. Gesteund worden onder meer inclusieve sportdeelname, toegankelijkheid van clubs, talentontwikkeling en coaching, sport in wijken waar sport moeilijk toegankelijk is, denksport en sportgerelateerde publicaties. Niet alle programma''s staan open voor ongevraagde aanvragen.',null,null,'Utrecht',null,null,null,'https://www.kindora.co/en/funders/stichting-nationaal-fonds-voor-de-sport')
), u as (update public.funders f set
 algemene_beschrijving = coalesce(nullif(f.algemene_beschrijving,''), v.beschr),
 website = coalesce(nullif(f.website,''), v.website),
 missie = coalesce(nullif(f.missie,''), v.missie),
 plaats = coalesce(nullif(f.plaats,''), v.plaats),
 bijdrage_min = coalesce(f.bijdrage_min, v.bmin::numeric),
 bijdrage_max = coalesce(f.bijdrage_max, v.bmax::numeric),
 bijdrage_toelichting = coalesce(nullif(f.bijdrage_toelichting,''), v.btoel),
 bandbreedte_bijdrage_id = coalesce(f.bandbreedte_bijdrage_id, (select b.id from public.bandbreedtes_bijdrage b where coalesce(f.bijdrage_max, v.bmax::numeric) is not null and coalesce(f.bijdrage_max, v.bmax::numeric) > b.bedrag_min and (b.bedrag_max is null or coalesce(f.bijdrage_max, v.bmax::numeric) <= b.bedrag_max) order by b.volgorde limit 1)),
 research_source = coalesce(f.research_source,'') || case when f.research_source is null or f.research_source='' then '' else ' | ' end || 'Verrijking goedgekeurde fondsen ronde12, 17-10-2026 (Claude)',
 last_researched_at = now()
from v where f.id = v.id::uuid returning 1)
select count(*) bijgewerkt from u;